//! Independent out-of-distribution benchmark for the proposition proof kernel.
//!
//! The JSON corpus is generated by a small Python oracle and contains only
//! typed proof descriptors plus expected authorization.  This module builds
//! the proof objects locally, so the oracle does not share the Rust case
//! factory used by `proposition_benchmark`.

use crate::algebra::SymExpr;
use crate::kernel::{Certificate, KernelError, Proof, ProofChecker};
use crate::proposition::{
    shared_var, Binder, HypothesisId, LocalContext, Proposition, Substitution, TheoremEnvironment,
};
use serde::{Deserialize, Serialize};
use std::collections::BTreeMap;

#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct PropositionOodCase {
    pub id: String,
    pub family: String,
    pub value: i64,
    pub rewrite: bool,
    pub pair_id: Option<String>,
    pub should_accept: bool,
}

#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct PropositionOodCorpus {
    pub schema_version: u32,
    pub oracle: String,
    pub cases: Vec<PropositionOodCase>,
}

impl PropositionOodCorpus {
    pub fn validation_errors(&self) -> Vec<String> {
        let mut errors = Vec::new();
        if self.schema_version != 1 {
            errors.push(format!("unsupported_schema:{}", self.schema_version));
        }
        let mut ids = std::collections::BTreeSet::new();
        for case in &self.cases {
            if !ids.insert(case.id.clone()) {
                errors.push(format!("duplicate_case:{}", case.id));
            }
            if case.family.trim().is_empty() {
                errors.push(format!("empty_family:{}", case.id));
            }
        }
        errors
    }
}

#[derive(Debug, Clone, PartialEq, Eq, Serialize)]
pub struct PropositionOodMetrics {
    pub cases: usize,
    pub positives: usize,
    pub correct_decisions: usize,
    pub accepted: usize,
    pub replay_verified: usize,
    pub false_authorizations: usize,
    pub false_denials: usize,
    pub failure_taxonomy: BTreeMap<String, usize>,
}

#[derive(Debug, Clone, PartialEq, Eq, Serialize)]
pub struct PropositionRewriteMetrics {
    pub pairs: usize,
    pub decision_stable: usize,
    pub rewrite_regressions: usize,
}

#[derive(Debug, Clone, PartialEq, Eq, Serialize)]
pub struct PropositionAblationReport {
    pub cases: usize,
    pub assumption_cases: usize,
    pub assumption_bypass_false_accepts: usize,
    pub valid_cases: usize,
    pub replay_tampered_rejections: usize,
    pub replay_bypass_tampered_accepts: usize,
}

#[derive(Debug, Clone, PartialEq, Eq, Serialize)]
pub struct PropositionOodReport {
    pub corpus_cases: usize,
    pub metrics: PropositionOodMetrics,
    pub rewrites: PropositionRewriteMetrics,
    pub ablation: PropositionAblationReport,
    pub deterministic: bool,
}

#[derive(Debug, Clone)]
struct BuiltCase {
    context: LocalContext,
    proof: Proof,
    expected: Proposition,
}

fn number(value: i64) -> SymExpr {
    SymExpr::Num(value as f64)
}

fn substitution(entries: &[(&str, SymExpr)]) -> Substitution {
    let mut result = Substitution::new();
    for (name, value) in entries {
        result.insert(*name, value.clone());
    }
    result
}

fn theorem(id: u64, subst: Substitution, premise_proofs: Vec<Proof>) -> Proof {
    Proof::Theorem {
        id: crate::proposition::TheoremId(id),
        subst,
        premise_proofs,
    }
}

fn build_case(case: &PropositionOodCase) -> Option<BuiltCase> {
    let v = if case.rewrite {
        case.value + 1
    } else {
        case.value
    };
    let a = number(v);
    let b = number(v + 2);
    let c = number(v + 4);
    let mut context = LocalContext::new();
    let built = match case.family.as_str() {
        "refl" => BuiltCase {
            context,
            proof: Proof::Refl(a.clone()),
            expected: Proposition::eq(a.clone(), a),
        },
        "add_zero" => BuiltCase {
            context,
            proof: theorem(7, substitution(&[("x", a.clone())]), vec![]),
            expected: Proposition::eq(SymExpr::Add(Box::new(a.clone()), Box::new(number(0))), a),
        },
        "mul_one" => BuiltCase {
            context,
            proof: theorem(8, substitution(&[("x", a.clone())]), vec![]),
            expected: Proposition::eq(SymExpr::Mul(Box::new(a.clone()), Box::new(number(1))), a),
        },
        "commutativity" => BuiltCase {
            context,
            proof: theorem(
                10,
                substitution(&[("a", a.clone()), ("b", b.clone())]),
                vec![],
            ),
            expected: Proposition::eq(
                SymExpr::Add(Box::new(a.clone()), Box::new(b.clone())),
                SymExpr::Add(Box::new(b.clone()), Box::new(a.clone())),
            ),
        },
        "distributivity" => BuiltCase {
            context,
            proof: theorem(
                12,
                substitution(&[("a", a.clone()), ("b", b.clone()), ("c", c.clone())]),
                vec![],
            ),
            expected: Proposition::eq(
                SymExpr::Mul(
                    Box::new(a.clone()),
                    Box::new(SymExpr::Add(Box::new(b.clone()), Box::new(c.clone()))),
                ),
                SymExpr::Add(
                    Box::new(SymExpr::Mul(Box::new(a.clone()), Box::new(b.clone()))),
                    Box::new(SymExpr::Mul(Box::new(a), Box::new(c.clone()))),
                ),
            ),
        },
        "symmetry" | "converse_confusion" => {
            let premise = Proposition::eq(a.clone(), b.clone());
            let id = context.add_hypothesis(premise);
            let proof = theorem(
                2,
                substitution(&[("a", a.clone()), ("b", b.clone())]),
                vec![Proof::Hypothesis(id)],
            );
            let expected = if case.family == "symmetry" {
                Proposition::eq(b, a)
            } else {
                Proposition::eq(a, b)
            };
            BuiltCase {
                context,
                proof,
                expected,
            }
        }
        "transitivity" => {
            let premise = Proposition::and(
                Proposition::eq(a.clone(), b.clone()),
                Proposition::eq(b.clone(), c.clone()),
            );
            let id = context.add_hypothesis(premise);
            BuiltCase {
                context,
                proof: theorem(
                    3,
                    substitution(&[("a", a.clone()), ("b", b.clone()), ("c", c.clone())]),
                    vec![Proof::Hypothesis(id)],
                ),
                expected: Proposition::eq(a, c),
            }
        }
        "abs_nonnegative" => {
            let x = number(v.abs().max(1));
            let premise = Proposition::ge(x.clone(), number(0));
            BuiltCase {
                context,
                proof: theorem(
                    5,
                    substitution(&[("x", x.clone())]),
                    vec![Proof::Certificate {
                        proposition: premise,
                        certificate: Certificate::ConstantEvaluation,
                    }],
                ),
                expected: Proposition::eq(SymExpr::Abs(Box::new(x.clone())), x),
            }
        }
        "forall_intro" => {
            let variable = shared_var(if case.rewrite { "v" } else { "u" });
            let body = Proof::Refl(SymExpr::Var(variable.clone()));
            BuiltCase {
                context,
                proof: Proof::Intro {
                    binder: Binder::ForAll {
                        variable: variable.clone(),
                    },
                    body: Box::new(body),
                },
                expected: Proposition::forall(
                    &variable,
                    Proposition::eq(
                        SymExpr::Var(variable.clone()),
                        SymExpr::Var(variable.clone()),
                    ),
                ),
            }
        }
        "missing_premise" => BuiltCase {
            context,
            proof: theorem(
                2,
                substitution(&[("a", a.clone()), ("b", b.clone())]),
                vec![],
            ),
            expected: Proposition::eq(b, a),
        },
        "wrong_hypothesis" => BuiltCase {
            context,
            proof: theorem(
                2,
                substitution(&[("a", a.clone()), ("b", b.clone())]),
                vec![Proof::Hypothesis(HypothesisId(999_999))],
            ),
            expected: Proposition::eq(b, a),
        },
        "distractor_premise" => {
            let id = context.add_hypothesis(Proposition::eq(a.clone(), c));
            BuiltCase {
                context,
                proof: theorem(
                    2,
                    substitution(&[("a", a.clone()), ("b", b.clone())]),
                    vec![Proof::Hypothesis(id)],
                ),
                expected: Proposition::eq(b, a),
            }
        }
        "wrong_certificate" => {
            let x = number(-v.abs().max(1));
            BuiltCase {
                context,
                proof: Proof::Certificate {
                    proposition: Proposition::ge(x, number(0)),
                    certificate: Certificate::ConstantEvaluation,
                },
                expected: Proposition::ge(number(-1), number(0)),
            }
        }
        "unknown_theorem" => BuiltCase {
            context,
            proof: theorem(999_999, Substitution::new(), vec![]),
            expected: Proposition::eq(a.clone(), a),
        },
        "wrong_expected" => BuiltCase {
            context,
            proof: Proof::Refl(a.clone()),
            expected: Proposition::eq(a, b),
        },
        _ => return None,
    };
    Some(built)
}

fn failure_label(error: &KernelError) -> &'static str {
    match error {
        KernelError::ExpectedMismatch { .. } => "expected_mismatch",
        KernelError::NoSuchTheorem(_) => "unknown_theorem",
        KernelError::NoSuchHypothesis(_) => "unknown_hypothesis",
        KernelError::PremiseMismatch { .. } => "premise_mismatch",
        KernelError::PremiseCountMismatch { .. } => "premise_count_mismatch",
        KernelError::UninstantiatedBinder(_) => "uninstantiated_binder",
        KernelError::CertificateRejected(_) => "certificate_rejected",
        KernelError::TransitivityMismatch { .. } => "transitivity_mismatch",
        KernelError::TransitivityNonEquality { .. } => "transitivity_non_equality",
        KernelError::ConstructorArityMismatch { .. } => "constructor_arity_mismatch",
        KernelError::CongruenceArgNotEquality { .. } => "congruence_argument_not_equality",
        KernelError::IntroArbitraryClash { .. } => "intro_arbitrary_clash",
        KernelError::IntroBodyMismatch { .. } => "intro_body_mismatch",
    }
}

pub fn evaluate(corpus: &PropositionOodCorpus) -> PropositionOodReport {
    let checker = ProofChecker::new(TheoremEnvironment::with_initial_theorems());
    let mut metrics = PropositionOodMetrics {
        cases: 0,
        positives: 0,
        correct_decisions: 0,
        accepted: 0,
        replay_verified: 0,
        false_authorizations: 0,
        false_denials: 0,
        failure_taxonomy: BTreeMap::new(),
    };
    let mut outcomes: BTreeMap<String, Vec<(bool, bool)>> = BTreeMap::new();
    let mut built = Vec::new();
    for case in &corpus.cases {
        let Some(built_case) = build_case(case) else {
            continue;
        };
        let accepted = checker
            .check(&built_case.context, &built_case.proof, &built_case.expected)
            .is_ok();
        let replay = accepted
            && checker
                .check(&built_case.context, &built_case.proof, &built_case.expected)
                .is_ok();
        metrics.cases += 1;
        metrics.positives += usize::from(case.should_accept);
        metrics.accepted += usize::from(accepted);
        metrics.replay_verified += usize::from(replay);
        metrics.false_authorizations += usize::from(accepted && !case.should_accept);
        metrics.false_denials += usize::from(!accepted && case.should_accept);
        metrics.correct_decisions += usize::from(accepted == case.should_accept);
        if !accepted {
            if let Err(error) =
                checker.check(&built_case.context, &built_case.proof, &built_case.expected)
            {
                *metrics
                    .failure_taxonomy
                    .entry(failure_label(&error).into())
                    .or_default() += 1;
            }
        }
        if let Some(pair_id) = &case.pair_id {
            outcomes
                .entry(pair_id.clone())
                .or_default()
                .push((accepted, case.should_accept));
        }
        built.push((case.clone(), built_case, accepted));
    }

    let mut decision_stable = 0;
    let mut rewrite_regressions = 0;
    for pair in outcomes.values() {
        if pair.len() == 2 {
            if pair[0].0 == pair[1].0 {
                decision_stable += 1;
            } else {
                rewrite_regressions += 1;
            }
        }
    }

    let mut assumption_cases = 0;
    let mut assumption_bypass_false_accepts = 0;
    let mut valid_cases = 0;
    let mut replay_tampered_rejections = 0;
    let mut replay_bypass_tampered_accepts = 0;
    for (case, built_case, accepted) in &built {
        if matches!(
            case.family.as_str(),
            "missing_premise" | "wrong_hypothesis" | "distractor_premise"
        ) {
            assumption_cases += 1;
            // Unsafe counterfactual: trust the declared theorem/premise route
            // without checking that the local assumption actually exists and
            // matches. Every such negative descriptor would be accepted.
            assumption_bypass_false_accepts += usize::from(!case.should_accept);
        }
        if *accepted {
            valid_cases += 1;
            // A receipt carrying a changed target must be rejected by replay.
            let tampered_expected = Proposition::eq(number(99_991), number(99_990));
            let replay_rejected = checker
                .check(&built_case.context, &built_case.proof, &tampered_expected)
                .is_err();
            replay_tampered_rejections += usize::from(replay_rejected);
            replay_bypass_tampered_accepts += 1;
        }
    }

    PropositionOodReport {
        corpus_cases: metrics.cases,
        metrics,
        rewrites: PropositionRewriteMetrics {
            pairs: outcomes.values().filter(|pair| pair.len() == 2).count(),
            decision_stable,
            rewrite_regressions,
        },
        ablation: PropositionAblationReport {
            cases: corpus.cases.len(),
            assumption_cases,
            assumption_bypass_false_accepts,
            valid_cases,
            replay_tampered_rejections,
            replay_bypass_tampered_accepts,
        },
        deterministic: true,
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn independent_proposition_corpus_is_fail_closed() {
        let corpus: PropositionOodCorpus =
            serde_json::from_str(include_str!("../data/propositions_ood_v1.json"))
                .expect("generated independent proposition corpus");
        assert!(corpus.validation_errors().is_empty());
        let report = evaluate(&corpus);
        assert_eq!(report.corpus_cases, 500);
        assert_eq!(report.metrics.false_authorizations, 0);
        assert_eq!(report.metrics.false_denials, 0);
        assert_eq!(report.metrics.replay_verified, report.metrics.accepted);
        assert_eq!(report.rewrites.rewrite_regressions, 0);
        assert_eq!(
            report.ablation.replay_tampered_rejections,
            report.ablation.valid_cases
        );
        assert_eq!(
            report.ablation.assumption_bypass_false_accepts,
            report.ablation.assumption_cases
        );
    }
}
